<script setup lang="ts">
import {ref,reactive,onMounted,onUnmounted} from 'vue';import {admin,headers,upload,mutationKey} from '../../../shared/api';import type {Page} from '../../../shared/types';import type {Knowledge,Job} from '../../../shared/adminTypes';import {useLoad} from '../../../shared/useLoad';import {ElMessage} from 'element-plus'
const result=ref<Page<Knowledge>>(),keyword=ref(''),edit=ref(false),selected=ref<Knowledge>(),job=ref<Job>(),key=mutationKey(),{loading,error,run}=useLoad();let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const form=reactive({title:'',category:'feeding',petType:'dog',format:'article' as 'article'|'qa',content:'',question:'',answer:'',sourceName:'',sourceUrl:'',status:'draft',breedNames:[] as string[]})
const pageNumber=ref(1)
const load=()=>run(async()=>{result.value=await admin('GET','/admin/knowledge/entries',undefined,{keyword:keyword.value,page:pageNumber.value,pageSize:20})})
function open(row?:Knowledge){selected.value=row;Object.assign(form,row?{title:row.title,category:row.category,petType:row.petType,format:row.format,content:row.content||'',question:row.question||'',answer:row.answer||'',sourceName:row.sourceName,sourceUrl:row.sourceUrl||'',status:row.status,breedNames:row.breedNames}:{title:'',category:'feeding',petType:'dog',format:'article',content:'',question:'',answer:'',sourceName:'',sourceUrl:'',status:'draft',breedNames:[]});edit.value=true}
const save=()=>run(async()=>{if(!form.title.trim()||!form.sourceName.trim()||(form.format==='article'?!form.content.trim():!form.question.trim()||!form.answer.trim()))throw new Error('请填写标题、内容和来源');const body={title:form.title,category:form.category,petType:form.petType,format:form.format,sourceName:form.sourceName,sourceUrl:form.sourceUrl||null,status:form.status,breedNames:form.breedNames,...(form.format==='article'?{content:form.content}:{question:form.question,answer:form.answer}),...(selected.value?{version:selected.value.version}:{})};await admin(selected.value?'PUT':'POST',selected.value?`/admin/knowledge/entries/${selected.value.id}`:'/admin/knowledge/entries',body);ElMessage.success('知识已保存，发布内容需等待索引就绪');edit.value=false;result.value=await admin('GET','/admin/knowledge/entries',undefined,{page:pageNumber.value,pageSize:20})})
async function poll(){if(!job.value||disposed)return;try{job.value=await admin('GET',`/admin/knowledge/jobs/${job.value.id}`);if(!disposed&&['pending','queued','running','processing'].includes(job.value!.status))timer=setTimeout(()=>void poll(),2000);else void load()}catch(e){error.value=e instanceof Error?e.message:'任务查询失败'}}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await run(async()=>{const asset=await upload('admin',file,'knowledge_import');const body={fileId:asset.id};job.value=await admin('POST','/admin/knowledge/import-jobs',body,undefined,key('/knowledge/import',body));void poll()});(event.target as HTMLInputElement).value=''}
async function rebuild(){await run(async()=>{const body={scope:'all'};job.value=await admin('POST','/admin/knowledge/index-rebuild-jobs',body,undefined,key('/knowledge/rebuild',body));void poll()})}
async function template(){await run(async()=>{const res=await fetch('/api/v1/admin/knowledge/import-template?format=csv',{headers:headers('admin')});if(!res.ok)throw new Error('模板下载失败');const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download='knowledge-import-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
onMounted(load);onUnmounted(()=>{disposed=true;clearTimeout(timer)})
</script>
<template><div class="section-title"><div><p class="eyebrow">KNOWLEDGE LIBRARY</p><h2>让每次回答，有据可依。</h2></div><el-button type="primary" size="large" @click="open()">＋ 新建知识</el-button></div><div class="toolbar"><el-input v-model="keyword" placeholder="搜索知识标题或内容" @keyup.enter="load"/><el-button @click="load">查询</el-button><el-button @click="template">下载 CSV 模板</el-button><label><span class="small muted">导入 Excel / CSV</span><input type="file" accept=".csv,.xlsx" :disabled="loading" @change="importFile"></label><el-button :loading="loading" @click="rebuild">重建索引</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="job" :title="`任务 ${job.id} · ${job.status} · 成功 ${job.successCount||0} 条 / 失败 ${job.failedCount||0} 条`" type="info" :closable="false"/><el-alert v-if="job?.errorMessage" :title="job.errorMessage" type="warning" :closable="false"/><div class="table-panel"><el-table :data="result?.items||[]" v-loading="loading"><el-table-column prop="title" label="标题" min-width="260"/><el-table-column label="宠物类型" min-width="120"><template #default="{row}">{{row.petType==='cat'?'猫':row.petType==='dog'?'狗':'猫和狗'}}</template></el-table-column><el-table-column label="发布状态" min-width="130"><template #default="{row}">{{row.status==='published'?'已发布':row.status==='draft'?'草稿':'已归档'}}</template></el-table-column><el-table-column prop="indexStatus" label="索引状态" min-width="140"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-if="result" v-model:current-page="pageNumber" :page-size="20" :total="result.total" layout="prev,pager,next" @current-change="load"/></div><el-dialog v-model="edit" :title="selected?'编辑知识':'新建知识'" width="680px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120"/></el-form-item><div class="form-grid"><el-form-item label="宠物类型"><el-select v-model="form.petType"><el-option value="dog" label="狗"/><el-option value="cat" label="猫"/><el-option value="both" label="猫和狗"/></el-select></el-form-item><el-form-item label="知识分类"><el-select v-model="form.category"><el-option v-for="c in [['feeding','饲养'],['breed','品种'],['training','训练'],['health','健康'],['grooming','美容']]" :key="c[0]" :value="c[0]" :label="c[1]"/></el-select></el-form-item></div><el-form-item label="内容格式"><el-radio-group v-model="form.format"><el-radio value="article">文章</el-radio><el-radio value="qa">问答对</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.format==='article'" label="正文"><el-input v-model="form.content" type="textarea" :rows="5"/></el-form-item><template v-else><el-form-item label="问题"><el-input v-model="form.question"/></el-form-item><el-form-item label="答案"><el-input v-model="form.answer" type="textarea" :rows="5"/></el-form-item></template><el-form-item label="来源名称"><el-input v-model="form.sourceName" placeholder="例如：门店饲养手册"/></el-form-item><el-form-item label="公开来源链接（可选）"><el-input v-model="form.sourceUrl" placeholder="https://…"/></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option value="draft" label="保存为草稿"/><el-option value="published" label="已审核，发布"/><el-option value="archived" label="归档"/></el-select></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="edit=false">取消</el-button><el-button type="primary" :loading="loading" @click="save">保存知识</el-button></template></el-dialog></template>
